const faltando = alvos
  .map((item) => item.caminho)
  .filter((caminho) => !existsSync(caminho));

if (faltando.length > 0 || !existsSync("package.json")) {
  console.error("ERRO: nao encontrei estes arquivos do projeto:\n");
  faltando.forEach((caminho) => console.error("   - " + caminho));
  console.error(
    "\nColoque este script na pasta raiz do projeto (a mesma que tem o package.json) e rode de novo.\n",
  );
  process.exit(1);
}

let mudou = 0;
let jaEstava = 0;

for (const alvo of alvos) {
  const atual = readFileSync(alvo.caminho, "utf8");
  const usaCRLF = atual.includes("\r\n");
  const novo = Buffer.from(alvo.conteudo, "base64").toString("utf8");
  const saida = usaCRLF
    ? novo.replace(/\r\n/g, "\n").replace(/\n/g, "\r\n")
    : novo.replace(/\r\n/g, "\n");

  if (atual === saida) {
    jaEstava += 1;
    console.log("  [pulou] " + alvo.rotulo + " (ja estava aplicada)");
    continue;
  }

  writeFileSync(alvo.caminho, saida, "utf8");
  mudou += 1;
  console.log("  [ok]    " + alvo.rotulo);
}

console.log(
  "\nPronto! " +
    mudou +
    " arquivo(s) atualizado(s)" +
    (jaEstava > 0 ? ", " + jaEstava + " ja estava(m) no lugar" : "") +
    ".\n",
);
console.log("Agora rode:  npm run build\n");
